contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint deposit, uint collectAmt) public payable {
        require(address(this).balance >= deposit);
        require(deposit > 0);
        uint balBefore = address(c).balance;
        uint beforeTime = block.timestamp + 1000;
        c.Put{value: deposit}(beforeTime);
        uint recBal = c.Acc(address(this)).balance;
        assert(address(c).balance == balBefore + deposit && recBal == deposit);
        // Now test that Collect with an amount larger than balance neither
        // reverts nor moves Ether out of the contract.
        bool reverted;
        uint balAfter = address(c).balance;
        try c.Collect(collectAmt) { reverted = false; } catch { reverted = true; }
        assert(reverted || address(c).balance == balAfter);
    }
    receive() external payable {}
}

